arguments.command:
python3 -c "import json; p='/root/cycle_margin_analysis.json';
obj=json.load(open(p));
# basic checks
ths=obj['therapies'];
assert [t['therapy'] for t in ths]==sorted([t['therapy'] for t in ths]);
# drug cost equality check
for t in ths:
    if round(t['annual_drug_cost_30_day'],2)!=round(t['annual_drug_cost_90_day'],2):
        raise SystemExit(f\"Drug cost mismatch for {t['therapy']}: {t['annual_drug_cost_30_day']} vs {t['annual_drug_cost_90_day']}\")
# totals consistency
sum30=round(sum(t['annual_margin_30_day'] for t in ths),2)
sum90=round(sum(t['annual_margin_90_day'] for t in ths),2)
sumdiff=round(sum(t['annual_margin_difference'] for t in ths),2)
assert round(obj['totals']['total_annual_margin_30_day'],2)==sum30
assert round(obj['totals']['total_annual_margin_90_day'],2)==sum90
assert round(obj['totals']['total_annual_margin_difference'],2)==sumdiff
assert round(obj['totals']['absolute_total_margin_difference'],2)==round(abs(sumdiff),2)
print('checks_ok')"

